def parenteses_balanceados(texto):
    pilha = []
    pares = {')': '(', ']': '[', '}': '{'}
    for caractere in texto:
        if caractere in '([{':
            pilha.append(caractere)
        elif caractere in ')]}':
            if not pilha or pilha[-1] != pares[caractere]:
                return False
            pilha.pop()
    return not pilha
